### Finding 4: In `mcp-skills.ts`, `validateSkill` rejects valid root skill directories when URL contains uppercase or percent-encoded UTF-8 characters

* **Severity:** Medium
* **Evidence:**
  In `mcp-skills.ts`:
  ```typescript
  function safeUri(uri: string): string {
    const url = new URL(uri);
    ...
    normalizeAuthority(url);
    url.pathname = url.pathname.split("/").map(s => encodeURIComponent(decodeURIComponent(s))).join("/");
    return url.href;
  }
  function rootOf(uri: string): string {
    uri = safeUri(uri);
    if (!uri.endsWith("/SKILL.md")) throw new Error("Skill URI must end in /SKILL.md");
    return uri.slice(0, -"/SKILL.md".length);
  }
  export function validateSkill(raw: unknown): SkillEntry {
    const entry = entrySchema.parse(raw);
    const root = rootOf(entry.uri);
    const name = decodeURIComponent(root.slice(root.lastIndexOf("/") + 1));
    if (name !== entry.frontmatter.name || !/^[\p{Ll}\p{Lo}\p{N}]+(?:-[\p{Ll}\p{Lo}\p{N}]+)*$/u.test(name))
      throw new Error("Skill name does not match its directory");
  ```
* **Minimal Regression:**
  If a server advertises `uri: "skill://server/My-Skill/SKILL.md"` with `frontmatter.name: "My-Skill"`, `root` becomes `"skill://server/My-Skill"`, and `name` is `"My-Skill"`.
  The regex `/^[\p{Ll}\p{Lo}\p{N}]+(?:-[\p{Ll}\p{Lo}\p{N}]+)*$/u` only allows lowercase letters (`\p{Ll}`), other letters (`\p{Lo}`), and numbers (`\p{N}`). Uppercase letters (`\p{Lu}`) are rejected, throwing `"Skill name does not match its directory"`. Valid skills with mixed-case directory names fail schema validation during `skills/list` or `skills/get`.

